async def act(page):
    """
    Continue from the current New Product edit screen and complete the product details:
    - Set Status to Enabled
    - Open Prices tab and set Price to 60
    - Set Size to S and Color to Blue (if those attribute controls exist)
    - Open Inventory tab and set Qty to 50 and mark product In Stock
    - Save the product (final action)

    NOTE: Only accessibility-centric selectors are used (get_by_role, get_by_label, select_option, check, fill, click).
    """
    # Ensure the page is stable before interacting
    await page.wait_for_load_state("networkidle")

    # There are no knowledge-base helper functions available in the environment; all actions use Playwright page methods.

    # 1) Set Status -> Enabled (combobox label in the current General tab)
    status_cb = page.get_by_role("combobox", name="Status *")
    if await status_cb.count() > 0:
        # Use select_option by visible label
        await status_cb.select_option(label="Enabled")

    # 2) Open the Prices section/tab so the Price input becomes visible
    if await page.get_by_role("link", name="Prices").count() > 0:
        await page.get_by_role("link", name="Prices").click()
    elif await page.get_by_role("tab", name="Prices").count() > 0:
        await page.get_by_role("tab", name="Prices").click()
    elif await page.get_by_role("button", name="Prices").count() > 0:
        await page.get_by_role("button", name="Prices").click()

    # small pause to allow the Prices section to render
    await page.wait_for_timeout(400)

    # 3) Fill Price. Try the exact required label first (common Magento label is "Price *").
    price_filled = False
    price_label_exact = page.get_by_label("Price *", exact=True)
    if await price_label_exact.count() == 1:
        await price_label_exact.fill("60")
        price_filled = True

    # fallback: try non-exact "Price" label but ensure we target a single element if present
    if not price_filled:
        price_label_generic = page.get_by_label("Price")
        if await price_label_generic.count() == 1:
            await price_label_generic.fill("60")
            price_filled = True

    # 4) Set attributes Size -> S and Color -> Blue if they are present on the page
    # Size
    if await page.get_by_label("Size").count() > 0:
        try:
            await page.get_by_label("Size").select_option(label="S")
        except Exception:
            # fallback: radio option named "S"
            if await page.get_by_role("radio", name="S").count() > 0:
                await page.get_by_role("radio", name="S").check()

    # Color
    if await page.get_by_label("Color").count() > 0:
        try:
            await page.get_by_label("Color").select_option(label="Blue")
        except Exception:
            if await page.get_by_role("radio", name="Blue").count() > 0:
                await page.get_by_role("radio", name="Blue").check()

    # 5) Open Inventory tab/section
    if await page.get_by_role("link", name="Inventory").count() > 0:
        await page.get_by_role("link", name="Inventory").click()
    elif await page.get_by_role("tab", name="Inventory").count() > 0:
        await page.get_by_role("tab", name="Inventory").click()
    elif await page.get_by_role("button", name="Inventory").count() > 0:
        await page.get_by_role("button", name="Inventory").click()

    # allow inventory fields to appear
    await page.wait_for_timeout(400)

    # 6) Fill Qty = 50. Try common labels with exact matching to avoid multiple matches.
    qty_filled = False
    qty_exact = page.get_by_label("Qty", exact=True)
    if await qty_exact.count() == 1:
        await qty_exact.fill("50")
        qty_filled = True

    if not qty_filled:
        qty_alt = page.get_by_label("Quantity", exact=True)
        if await qty_alt.count() == 1:
            await qty_alt.fill("50")
            qty_filled = True

    # 7) Ensure product is In Stock. Try combobox or radio/checkbox fallbacks.
    if await page.get_by_label("Stock Availability").count() > 0:
        try:
            await page.get_by_label("Stock Availability").select_option(label="In Stock")
        except Exception:
            if await page.get_by_role("radio", name="In Stock").count() > 0:
                await page.get_by_role("radio", name="In Stock").check()
    else:
        # try input/checkbox labeled "In Stock"
        if await page.get_by_label("In Stock").count() > 0:
            try:
                await page.get_by_label("In Stock").check()
            except Exception:
                # radio fallback
                if await page.get_by_role("radio", name="In Stock").count() > 0:
                    await page.get_by_role("radio", name="In Stock").check()

    # 8) Save the product. This is the final action because it may navigate away.
    if await page.get_by_role("button", name="Save").count() > 0:
        await page.get_by_role("button", name="Save").click()
    elif await page.get_by_role("button", name="Save and Continue Edit").count() > 0:
        await page.get_by_role("button", name="Save and Continue Edit").click()

    # Let the save complete; do not attempt further selectors after navigation.
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        await page.wait_for_timeout(1000)

